"use strict";
// A fictional repair-shop backup viewer; never reads files from the user's computer.
const oldComputerFiles={
 black:[{id:'ticket',folder:'照片备份',name:'DSC0130.JPG',date:'2008-10-17 22:35',image:'images/tide/deep/ticket.svg',body:'从N73复制到电脑的同一张车票照片，未改动原图。'},{id:'mirror',folder:'照片备份',name:'DSC0150.JPG',date:'2008-10-18 03:44',image:'images/tide/deep/mirror.svg',body:'许舟后来复制的窗边照片。文件名未变。'},{id:'chat',folder:'QQ备份',name:'阿巡_离线记录.txt',date:'2008-10-19 00:37',body:'阿巡：昨晚你发来那两份的时候，我这边掉线了。\n许舟（旧记录）：电池没买到，店关门了。\n阿巡：先留原卡，不要拿转存到电脑的时间当录制时间。\n许舟（旧记录）：机器还在店里测皮带。\n\n这份导出没有附件，也不包含手机上后来收到的留言。'},{id:'bill',folder:'我的文档',name:'报账草稿.txt',date:'2008-10-17 21:50',body:'交通费留票，电池没有发票就在背面记店名。\n四块车费和班长那三块别写一起。\n录音机留店里，今晚只带手机和耳机。\n\n未填写：实际往返方式。'},{id:'sync',folder:'回收站',name:'复制记录.txt',date:'2008-10-18 10:06',body:'照片备份 / 保留原文件名。\nDSC0130.JPG → 已复制\nDSC0150.JPG → 已复制\n音频附件 → 未复制\n\n复制后没有执行删除原卡。文件修改时间可能由同步软件重新写入。'},{id:'lunch',folder:'我的文档',name:'周一要交的东西.txt',date:'2008-10-18 12:10',body:'实验报告黑白打印，不要彩印。\n班长的三块钱。\n把早餐照片洗一张给妈。\n阿巡那条耳机右边没海绵，别忘了还。'}],
 silver:[{id:'rehearsal',folder:'我的文档',name:'排练时间.txt',date:'2004-09-11 18:20',body:'排练改到周日，别照旧纸上的周六跑过去。\n先试效果器，再录一遍尾声。\n阿禾的银色手机留着录个小样，别压缩覆盖原文件。'},{id:'chat',folder:'QQ备份',name:'排练室留言.txt',date:'2004-09-12 10:10',body:'阿禾：最后那段掌声也留着吧。\n鼓手：不是正式演出，也留？\n阿禾：难得大家都在。\n鼓手：行，下次别站音箱旁边录。'},{id:'take',folder:'回收站',name:'录音小样清单.txt',date:'2004-09-12 10:12',body:'0918 / 尾声带掌声 / 原始小样\n旧时间表 / 已作废\n\n这里只是文件清单，没有保存录音本身。'},{id:'bus',folder:'我的文档',name:'回程零钱.txt',date:'2004-09-10 17:30',body:'坐车的钱别拿去买拨片。\n晚了先打电话回家。\n周末回来把衣服带来洗。'}],
 white:[{id:'photos',folder:'我的文档',name:'冲印清单.txt',date:'2010-06-05 21:18',body:'林恬 / 六班合照\n挑原图，不用网上转过的缩略图。\n照片背面别写学号，写名字就行。'},{id:'chat',folder:'QQ备份',name:'摄影社留言.txt',date:'2010-06-06 09:42',body:'林恬：最后一排能不能别裁掉。\n摄影社：有一张人齐，但边上糊了一点。\n林恬：就那张。不是每个人下次都能来了。'},{id:'contact',folder:'回收站',name:'取件便条.txt',date:'2010-06-06 10:05',body:'0612 / 原始照片冲印\n不要用上传到论坛后缩过的图。\n取照片的信封和白色5230放在一起。'},{id:'ordinary',folder:'我的文档',name:'暑假清单.txt',date:'2010-06-04 20:31',body:'还图书馆的书。\n合照多洗一份。\n给手机换张壁纸。\n等大家约好再说，不先订票。'}]
};
const oldComputerOwners={black:'N73 / 2008',silver:'6600 / 2004',white:'5230 / 2010'};
let computerView={owner:'black',folder:'我的文档',file:'',compare:false,zoom:false};
function computerState(){if(!tideDeep.computer)tideDeep.computer={restored:[],pins:[],notes:{black:'',silver:'',white:''}};return tideDeep.computer;}
try{const p=JSON.parse(localStorage.getItem(tideStoreKey)||'null')?.expansion?.computer;if(p){const valid=key=>typeof key==='string'&&Object.entries(oldComputerFiles).some(([owner,files])=>files.some(f=>key===owner+':'+f.id));tideDeep.computer={restored:Array.isArray(p.restored)?p.restored.filter(valid):[],pins:Array.isArray(p.pins)?p.pins.filter(valid).slice(0,6):[],notes:{}};for(const owner of Object.keys(oldComputerOwners))tideDeep.computer.notes[owner]=typeof p.notes?.[owner]==='string'?p.notes[owner].slice(0,1000):'';}}catch{}
function computerFile(id){return oldComputerFiles[computerView.owner]?.find(f=>f.id===id);}
function computerFolder(f){return f.folder==='回收站'&&computerState().restored.includes(computerView.owner+':'+f.id)?'我的文档':f.folder;}
function computerRestore(id,restore){const f=computerFile(id);if(!f||f.folder!=='回收站')return false;const s=computerState(),key=computerView.owner+':'+id;s.restored=s.restored.filter(x=>x!==key);if(restore)s.restored.push(key);tideSave();return true;}
function computerPin(id){const f=computerFile(id);if(!f)return false;const s=computerState(),key=computerView.owner+':'+id;if(s.pins.includes(key))s.pins=s.pins.filter(x=>x!==key);else{const own=s.pins.filter(x=>x.startsWith(computerView.owner+':'));if(own.length>=2)s.pins=s.pins.filter(x=>x!==own[0]);s.pins.push(key);}tideSave();return true;}
function computerFileMarkup(f){return `<article class="oldpc-file"><header><b>${escapeHTML(f.name)}</b><small>${f.date}</small></header>${f.image?`<button data-oldpc-zoom>${computerView.zoom?'还原':'放大图片'}</button><figure class="${computerView.zoom?'zoomed':''}"><img src="${f.image}" alt="${f.name}原创剧情插画"></figure>`:''}<p>${escapeHTML(f.body).replaceAll('\n','<br>')}</p></article>`;}
function computerMarkup(){const v=computerView,s=computerState(),files=oldComputerFiles[v.owner],file=computerFile(v.file),pins=files.filter(f=>s.pins.includes(v.owner+':'+f.id));return `<section class="oldpc"><header class="oldpc-title"><b>▣ 旧巷维修电脑</b><button data-oldpc-close>返回店里</button></header><div class="oldpc-info">本机故事备份 · 不访问你的电脑文件</div><nav class="oldpc-owners">${Object.entries(oldComputerOwners).map(([id,label])=>`<button data-oldpc-owner="${id}" aria-pressed="${id===v.owner}">${label}</button>`).join('')}</nav><div class="oldpc-address">地址　D:\\客人备份\\${oldComputerOwners[v.owner].replace(' / ','_')}\\${escapeHTML(v.folder)}</div><nav class="oldpc-folders">${['我的文档','照片备份','QQ备份','回收站'].map(folder=>`<button data-oldpc-folder="${folder}" aria-pressed="${folder===v.folder}">${folder==='回收站'?'♲':'▰'} ${folder}</button>`).join('')}<button data-oldpc-compare>并排查看 (${pins.length}/2)</button></nav>${v.compare?`<div class="oldpc-compare">${pins.map(computerFileMarkup).join('')||'<p>先打开文件，选择“放到桌面”，再回来并排查看。</p>'}</div><form data-oldpc-notes><label>桌边便笺<textarea name="notes" maxlength="1000" aria-label="电脑调查便笺">${escapeHTML(s.notes[v.owner]||'')}</textarea></label><button>保存便笺</button><span role="status" id="oldpc-saved"></span></form>`:file?`${computerFileMarkup(file)}<nav class="oldpc-actions"><button data-oldpc-pin="${file.id}">${s.pins.includes(v.owner+':'+file.id)?'从桌面收起':'放到桌面 / 对照'}</button>${file.folder==='回收站'?`<button data-oldpc-restore="${file.id}" data-restore="${computerFolder(file)==='回收站'?'yes':'no'}">${computerFolder(file)==='回收站'?'还原到我的文档':'放回回收站'}</button>`:''}<button data-oldpc-folder="${escapeHTML(v.folder)}">返回文件夹</button></nav>`:`<div class="oldpc-files">${files.filter(f=>computerFolder(f)===v.folder).map(f=>`<button data-oldpc-file="${f.id}"><b>${f.image?'▧':'▤'}</b><span>${f.name}</span><small>${f.date}</small></button>`).join('')||'<p>这个文件夹没有保存到文件。</p>'}</div>`}<footer class="oldpc-taskbar"><span>开始</span><span>${oldComputerOwners[v.owner]} 独立目录</span><small>原创虚构档案 / 本机自动保存</small></footer></section>`;}
function openOldComputer(){if(typeof experienceZone!=='undefined'&&experienceZone!=='story')return false;dialog('旧巷 / 维修电脑',computerMarkup());document.querySelector('#modal')?.classList.add('oldpc-dialog');return true;}
const computerShopMap=shopMap;shopMap=function(){return computerShopMap()+'<button class="oldpc-entry" data-oldpc-open>▣ 打开柜台旁的旧电脑 / 客人备份</button>';};
const computerExperience=renderExperienceHome;renderExperienceHome=function(){const html=computerExperience();return experienceZone==='story'?html+'<button class="oldpc-entry" data-oldpc-open>▣ 店里的旧电脑 / 翻看客人备份</button>':html;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-oldpc-open],[data-oldpc-close],[data-oldpc-owner],[data-oldpc-folder],[data-oldpc-file],[data-oldpc-pin],[data-oldpc-restore],[data-oldpc-compare],[data-oldpc-zoom]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-oldpc-open'))return openOldComputer();if(b.hasAttribute('data-oldpc-close')){document.querySelector('#modal')?.classList.remove('oldpc-dialog');return openShop();}if(b.dataset.oldpcOwner&&Object.hasOwn(oldComputerOwners,b.dataset.oldpcOwner)){computerView={owner:b.dataset.oldpcOwner,folder:'我的文档',file:'',compare:false,zoom:false};}if(b.dataset.oldpcFolder&&['我的文档','照片备份','QQ备份','回收站'].includes(b.dataset.oldpcFolder)){computerView.folder=b.dataset.oldpcFolder;computerView.file='';computerView.compare=false;computerView.zoom=false;}if(b.dataset.oldpcFile&&computerFile(b.dataset.oldpcFile)){computerView.file=b.dataset.oldpcFile;computerView.compare=false;computerView.zoom=false;}if(b.dataset.oldpcPin)computerPin(b.dataset.oldpcPin);if(b.dataset.oldpcRestore){computerRestore(b.dataset.oldpcRestore,b.dataset.restore==='yes');computerView.file='';}if(b.hasAttribute('data-oldpc-compare')){computerView.compare=true;computerView.zoom=false;}if(b.hasAttribute('data-oldpc-zoom'))computerView.zoom=!computerView.zoom;openOldComputer();});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-oldpc-notes]'))return;e.preventDefault();computerState().notes[computerView.owner]=String(new FormData(e.target).get('notes')||'').slice(0,1000);tideSave();const status=document.querySelector('#oldpc-saved');if(status)status.textContent='已保存在本机';});

document.querySelector('#modal')?.addEventListener?.('close',()=>document.querySelector('#modal')?.classList.remove('oldpc-dialog'));document.addEventListener('click',e=>{if(e.target.closest('#closedialog'))document.querySelector('#modal')?.classList.remove('oldpc-dialog');});
